import json,pathlib
r=pathlib.Path(__file__).resolve().parent.parent
long=json.loads((r/'artifacts/long_horizon_metrics.json').read_text());visual=json.loads((r/'artifacts/visual_metrics.json').read_text());samples=json.loads((r/'artifacts/visual_examples.json').read_text())
html='''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EchoWorld World Model Lab v2</title><style>body{margin:0;background:#081321;color:#e4eef6;font:15px system-ui,'Microsoft YaHei',sans-serif}header{padding:25px max(22px,calc((100% - 1150px)/2));background:#102235;border-bottom:1px solid #345}h1{margin:0 0 6px;font-size:25px}small,.muted{color:#9bb2c3}main{max-width:1150px;margin:auto;padding:20px;display:grid;grid-template-columns:1fr 1fr;gap:15px}.panel{background:#102335;border:1px solid #2c4657;border-radius:13px;padding:18px;min-width:0}.wide{grid-column:1/-1}h2{font-size:18px;margin:0 0 13px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{background:#192e40;border-radius:9px;padding:12px}.metric strong{font-size:22px;color:#a1e6ca;display:block}.metric small{font-size:11px}button,select{background:#224456;border:1px solid #497387;color:#e9f7fc;padding:9px 13px;border-radius:8px;cursor:pointer}button.active{background:#168e78}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.graph{width:100%;height:210px;background:#091a29;border-radius:10px}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:8px 5px;border-bottom:1px solid #304b5b;text-align:left}.imggrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.imggrid canvas{width:100%;image-rendering:pixelated;border:1px solid #44606a;border-radius:7px}.imggrid p{font-size:13px;text-align:center;color:#abc3d3}pre{white-space:pre-wrap;color:#adc8cf;font-size:12px;max-height:350px;overflow:auto}code{color:#b2e7c8}@media(max-width:760px){main{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}}</style></head><body><header><h1>ECHOWORLD <span style="color:#75e4bd">/ World Model Lab v2</span></h1><small>真实模型权重 · 10/50 步闭环预测 · 边界压力测试 · Action-conditioned Visual Dynamics</small></header><main><section class="panel wide"><h2>实验总结</h2><div class="metrics" id="top"></div><p class="muted">状态模型：固定 PyTorch MLP 权重闭环滚动；视觉模型：32×32 像素 CNN，输入上一帧和动作 One-hot，并预测下一帧。此网页展示已生成的独立评测数据和真实模型推理样本；网页本身不会重新训练。</p></section><section class="panel"><h2>① 自回归预测误差</h2><div class="controls"><button id="b10" class="active" onclick="plotRoll('rollout10')">10 步</button><button id="b50" onclick="plotRoll('rollout50')">50 步</button></div><canvas class="graph" id="roll" width="540" height="240"></canvas><p class="muted" id="rolltext"></p></section><section class="panel"><h2>② 边界状态专项测试</h2><div class="metrics" id="boundary"></div><p class="muted">湿度近阈值（45）、水坝/植物/闸门组合、极限湿度和生态值。含不可达状态，属于 OOD 压力测试，不能与常规轨迹直接混淆。</p><div id="worst"></div></section><section class="panel wide"><h2>③ Action-conditioned Visual Dynamics · 真实预测样本</h2><p class="muted">选择测试样本，查看上一帧、规则渲染下一帧（Ground Truth）和模型预测下一帧。所有图像取自训练完成的 PyTorch CNN 在独立测试集上的输出。</p><div class="controls"><label>测试样本 <select id="sample"></select></label><span id="action" style="padding:10px"></span></div><div class="imggrid"><div><canvas id="im0" width="32" height="32"></canvas><p>输入图像 t</p></div><div><canvas id="im1" width="32" height="32"></canvas><p>真实下一帧 t+1</p></div><div><canvas id="im2" width="32" height="32"></canvas><p>CNN 预测 t+1</p></div></div></section><section class="panel"><h2>④ 视觉预测量化评估</h2><div id="vm" class="metrics"></div><canvas class="graph" id="visual" width="540" height="240"></canvas></section><section class="panel"><h2>⑤ 结果解释及研发优先级</h2><p><b>为什么 50 步终点误差可能比 10 步低？</b> 状态饱和和轨迹分布不同。需要看整条误差曲线，不能声称误差随时间自然减少。</p><p><b>视觉模型是否超过基线？</b> <span id="interpret"></span></p><p><b>下一阶段：</b> 增加 <code>delta/residual prediction</code>、动作变化区域加权损失、更多有变化的采样、感知层面的物体恒存评估、多帧 ConvGRU 和定量消融。</p><p class="muted">这是动作条件视觉预测研究原型，非 Genie 4、非通用视频世界模型，图像来自程序化渲染的数据分布。</p></section></main><script>
const L=__LONG__,V=__VISUAL__,S=__SAMPLES__;
const $=x=>document.getElementById(x),fmt=x=>Number(x).toFixed(2),names={rain:'降雨',sun:'阳光',wind:'风向',seed:'播种',dam:'筑坝',open:'开闸'};
function metric(name,value){return `<div class="metric"><strong>${value}</strong><small>${name}</small></div>`}
$('top').innerHTML=metric('10 步终点 MAE',fmt(L.rollout10.final_mae)+' pp')+metric('50 步终点 MAE',fmt(L.rollout50.final_mae)+' pp')+metric('边界数值 MAE',fmt(L.boundary.numeric_mae)+' pp');
$('boundary').innerHTML=metric('边界状态-动作数',L.boundary.cases)+metric('布尔状态准确率',fmt(L.boundary.bool_accuracy*100)+'%')+metric('任一布尔变量出错率',fmt(L.boundary.any_boolean_failure_rate*100)+'%');
$('worst').innerHTML='<p>典型高误差案例</p><table><tr><th>动作</th><th>湿度</th><th>布尔错误</th><th>数值误差</th></tr>'+L.boundary.worst_cases.slice(0,5).map(v=>`<tr><td>${names[v.action]}</td><td>${v.state.wet}</td><td>${v.bool_failures.join(', ')||'无'}</td><td>${fmt(v.numeric_mae)} pp</td></tr>`).join('')+'</table>';
function lines(canvas,series,labels){let c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);c.strokeStyle='#395367';for(let i=1;i<5;i++){let y=h*i/5;c.beginPath();c.moveTo(38,y);c.lineTo(w-12,y);c.stroke()}let max=Math.max(.001,...series.flatMap(x=>x));for(let z=0;z<series.length;z++){c.beginPath();c.lineWidth=3;c.strokeStyle=['#7be3ba','#f5bb79'][z];series[z].forEach((v,i)=>{let x=38+(w-56)*i/Math.max(1,series[z].length-1),y=h-27-(h-44)*v/max;i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke();c.fillStyle=c.strokeStyle;c.font='12px sans-serif';c.fillText(labels[z],50,h-6-z*16)}c.fillStyle='#a6c0d0';c.fillText('0',7,h-27);c.fillText(fmt(max),6,17)}
function plotRoll(k){let q=L[k];$('b10').className=k==='rollout10'?'active':'';$('b50').className=k==='rollout50'?'active':'';lines($('roll'),[q.mean_mae_by_step],['MAE (pp)']);$('rolltext').textContent=`${q.episodes} 条轨迹；终点数值 MAE ${fmt(q.final_mae)}pp；P90 ${fmt(q.final_mae_p90)}pp；终点布尔准确率 ${fmt(q.final_bool_accuracy*100)}%。`;}
plotRoll('rollout10');$('vm').innerHTML=metric('测试集 MSE',V.test_mse.toFixed(4))+metric('复制前帧基线 MSE',V.copy_baseline_mse.toFixed(4))+metric('训练 / 测试样本',V.train_size+' / '+V.test_size);lines($('visual'),[V.history.map(x=>x.test_mse),V.history.map(x=>x.copy_baseline_mse)],['CNN test MSE','Copy baseline']);$('interpret').textContent=V.test_mse<V.copy_baseline_mse?'当前 CNN 优于复制前帧基线。':'目前 CNN 劣于复制前帧基线，说明训练尚不足以证明学习到有效的动作条件视觉变化。';
function drawFrame(id,v){let canvas=$(id),ctx=canvas.getContext('2d'),img=ctx.createImageData(32,32);for(let i=0;i<1024;i++){img.data[i*4]=v[i*3];img.data[i*4+1]=v[i*3+1];img.data[i*4+2]=v[i*3+2];img.data[i*4+3]=255}ctx.putImageData(img,0,0)}
S.forEach((x,i)=>$('sample').add(new Option(`样本 ${i+1} · ${names[x.action]}`,i)));function show(){let v=S[+$('sample').value];$('action').textContent='动作：'+names[v.action];drawFrame('im0',v.input);drawFrame('im1',v.ground_truth);drawFrame('im2',v.prediction)}$('sample').onchange=show;show();
</script></body></html>'''
(r/'EchoWorld_WorldModel_Lab.html').write_text(html.replace('__LONG__',json.dumps(long,separators=(',',':'))).replace('__VISUAL__',json.dumps(visual,separators=(',',':'))).replace('__SAMPLES__',json.dumps(samples,separators=(',',':'))),encoding='utf8')
